-- The canonical column contract every adapter maps into (mirrors docs/canonical_model.md).
{% macro canonical_columns(object_name) %}
  {%- set cols = {
    'SUPPLIER': [('SOURCE_SLOT','STRING'),('SOURCE_SYSTEM','STRING'),('SUPPLIER_ID','STRING'),('SUPPLIER_NAME','STRING'),('COUNTRY','STRING'),
                 ('TAX_ID','STRING'),('DUNS','STRING'),('PAYMENT_TERMS','STRING')],
    'PO_LINE': [('SOURCE_SLOT','STRING'),('SOURCE_SYSTEM','STRING'),('COMPANY_CODE','STRING'),('PLANT','STRING'),('PO_NUMBER','STRING'),('PO_ITEM','STRING'),
                ('SUPPLIER_ID','STRING'),('MATERIAL','STRING'),('ITEM_TEXT','STRING'),('MATERIAL_GROUP','STRING'),('QUANTITY','FLOAT'),('UOM','STRING'),
                ('NET_PRICE','FLOAT'),('NET_VALUE','FLOAT'),('CURRENCY','STRING'),('PO_DATE','DATE'),('DELIVERY_DATE','DATE'),('CONTRACT_ID','STRING')],
    'GOODS_RECEIPT': [('SOURCE_SLOT','STRING'),('SOURCE_SYSTEM','STRING'),('GR_DOC','STRING'),('PO_NUMBER','STRING'),('PO_ITEM','STRING'),('PLANT','STRING'),
                      ('SUPPLIER_ID','STRING'),('MATERIAL','STRING'),('GR_DATE','DATE'),('GR_QTY','FLOAT'),('GR_VALUE','FLOAT'),('CURRENCY','STRING')],
    'INVOICE_LINE': [('SOURCE_SLOT','STRING'),('SOURCE_SYSTEM','STRING'),('COMPANY_CODE','STRING'),('INVOICE_ID','STRING'),('PO_NUMBER','STRING'),('PO_ITEM','STRING'),
                     ('SUPPLIER_ID','STRING'),('INVOICE_DATE','DATE'),('INV_QTY','FLOAT'),('INV_AMOUNT','FLOAT'),('CURRENCY','STRING')],
    'PAYMENT': [('SOURCE_SLOT','STRING'),('SOURCE_SYSTEM','STRING'),('COMPANY_CODE','STRING'),('INVOICE_ID','STRING'),('SUPPLIER_ID','STRING'),('INVOICE_DATE','DATE'),
                ('DUE_DATE','DATE'),('PAYMENT_DATE','DATE'),('AMOUNT','FLOAT'),('DISCOUNT_TAKEN','FLOAT'),('CURRENCY','STRING'),('PAYMENT_TERMS','STRING')],
    'CONTRACT_ITEM': [('SOURCE_SLOT','STRING'),('SOURCE_SYSTEM','STRING'),('CONTRACT_ID','STRING'),('SUPPLIER_ID','STRING'),('MATERIAL','STRING'),('VALID_FROM','DATE'),
                      ('VALID_TO','DATE'),('CONTRACT_PRICE_USD','FLOAT')],
    'PRICE_CONDITION': [('SOURCE_SLOT','STRING'),('SOURCE_SYSTEM','STRING'),('PO_NUMBER','STRING'),('PO_ITEM','STRING'),('CONDITION_TYPE','STRING'),
                        ('CONDITION_RATE','FLOAT'),('CONDITION_VALUE','FLOAT'),('CURRENCY','STRING')],
  } -%}
  {{ return(cols[object_name]) }}
{% endmacro %}
